import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

it('reports a rejection whose string conversion throws (specs/hal-engine-config-hooks/spec.md#8)', async () => {
  const reason = {toString() { throw new Error('conversion failed'); }};
  const provider: AIProvider = {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> { throw reason; },
    async generateStructured<T>(): Promise<T> { return {} as T; },
  };
  const session: ChatSession = {sessionId: 's', userId: 'u', entries: []};
  const seen: Error[] = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
    hooks: {onError: async (_session, error) => void seen.push(error)},
  });
  const outcome = await orchestrator.processMessage(session).then(
    () => false,
    (error: unknown) => error === reason
  );
  expect({outcome, count: seen.length, isError: seen[0] instanceof Error, cause: seen[0]?.cause, message: seen[0]?.message}).toEqual({
    outcome: true, count: 1, isError: true, cause: reason, message: expect.any(String),
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runInBand src/orchestration/onErrorUnprintable.test.ts"

